--- /dev/null
+++ b/src/chrome/zhihu.ts
@@ -0,0 +1,167 @@
+import { ChromeBridge } from "./bridge.ts";
+import { logger } from "../logo.ts";
+import { TAB_GROUP_TITLE } from "./twitter.ts";
+
+/**
+ * 用 pi-chrome 抓知乎问题的第一个答案全文。
+ *
+ * 知乎的纯 HTTP 路径全是 403（桌面/移动 UA、`r.jina.ai` 都一样，页面是「安全验证」），
+ * 唯一可行的是复用仓库已有的桥：用户真实已登录的 Chrome。所以「抓不到」是常态路径之一，
+ * 一律 `{ ok: false, reason }`，不抛错——上层退回摘要片段继续出稿。
+ */
+
+export type ZhihuAnswerOutcome =
+  | { ok: true; url: string; text: string }
+  | { ok: false; reason: string };
+
+/**
+ * 页面内提取脚本。
+ *
+ * 必须短：CDP `Runtime.evaluate` 在扩展侧有 5 秒硬超时，跑不完就整条命令失败。
+ * 只取**第一个答案**：热榜条目一个答案的正文就够，全部答案拼起来是几万字，
+ * 翻译成本与噪声都不值。
+ */
+export const ANSWER_EXPRESSION = String.raw`(() => {
+  const el = document.querySelector('.List-item .RichText') || document.querySelector('.RichText');
+  return el ? (el.innerText || '').trim() : '';
+})()`;
+
+/** 等答案渲染出来的轮询间隔。 */
+const POLL_INTERVAL_MS = 1_000;
+
+/**
+ * 抽出来短于这个字数判失败。
+ *
+ * 200 字以下的「正文」多是登录提示、折叠占位、导航壳；把它们当答案全文
+ * 替换进成品比留摘要片段更糟。
+ */
+export const MIN_ANSWER_CHARS = 200;
+
+/** 等答案渲染的上限。登录墙不会自愈，等久了只是白等。 */
+export const DEFAULT_WAIT_MS = 15_000;
+
+export interface ZhihuFetchOptions {
+  /** 桥。默认 `ChromeBridge.connect()`，测试可注入替身。 */
+  bridge?: ChromeBridge;
+  /** 正文最少多少字才算抓到。 */
+  minChars?: number;
+  /** 等答案渲染的上限。 */
+  waitMs?: number;
+}
+
+/**
+ * 抓一个知乎问题的第一个答案全文。
+ *
+ * 后台标签页（不抢焦点）→ 等 `.RichText` 有内容 → 取 `innerText` → 关标签页。
+ */
+export async function fetchZhihuAnswer(
+  url: string,
+  options: ZhihuFetchOptions = {},
+): Promise<ZhihuAnswerOutcome> {
+  const minChars = options.minChars ?? MIN_ANSWER_CHARS;
+  const waitMs = options.waitMs ?? DEFAULT_WAIT_MS;
+
+  const fail = (reason: string): ZhihuAnswerOutcome => {
+    // 失败日志是「这台机器没开 Chrome」的唯一可见线索
+    logger.warn("zhihu answer failed", { url, reason });
+    return { ok: false, reason };
+  };
+
+  let bridge: ChromeBridge;
+  const ownsBridge = options.bridge === undefined;
+  if (options.bridge !== undefined) {
+    bridge = options.bridge;
+  } else {
+    try {
+      bridge = await ChromeBridge.connect();
+    } catch (error) {
+      return fail(`连不上 Chrome 桥：${error instanceof Error ? error.message : String(error)}`);
+    }
+  }
+
+  let tabId: number | undefined;
+  try {
+    // connect() 端口空着时会自起 server 而不报错，所以「扩展不在」必须单独判：
+    // 不判的话每条 tab.new 都要等满 30s 超时，十来个条目就是白等几分钟。
+    const status = await bridge.status();
+    if (!status.connected) {
+      return fail("Chrome 扩展没有在轮询");
+    }
+
+    const opened = (await bridge.send("tab.new", { url, groupTitle: TAB_GROUP_TITLE })) as
+      | { tab?: { id?: number } }
+      | undefined;
+    tabId = opened?.tab?.id;
+    if (typeof tabId !== "number") {
+      return fail("Chrome 没有返回标签页 id");
+    }
+
+    const text = await waitForAnswer(bridge, tabId, waitMs);
+    if (text === "") {
+      return fail(`等了 ${waitMs}ms 没等到答案正文（多半是登录墙 / 安全验证）`);
+    }
+    if (text.length < minChars) {
+      return fail(`答案正文只有 ${text.length} 字（低于 ${minChars} 字）`);
+    }
+    return { ok: true, url, text };
+  } catch (error) {
+    return fail(error instanceof Error ? error.message : String(error));
+  } finally {
+    if (tabId !== undefined) {
+      // 收尾：把自己开的标签页关掉，不留垃圾
+      try {
+        await bridge.send("tab.close", { targetId: tabId }, 10_000);
+      } catch (error) {
+        logger.warn("zhihu tab close failed", {
+          url,
+          tabId,
+          reason: error instanceof Error ? error.message : String(error),
+        });
+      }
+    }
+    if (ownsBridge) {
+      // 自己 connect 出来的桥（owner 模式会绑端口）用完释放，否则整个进程都占着 17318
+      await bridge.stop();
+    }
+  }
+}
+
+/**
+ * 每 1s 探一次答案正文，探到非空就返回。
+ *
+ * 探不到返回空串。单个探测失败（标签页还在加载）当成「还没有内容」继续等。
+ */
+async function waitForAnswer(bridge: ChromeBridge, tabId: number, timeoutMs: number): Promise<string> {
+  const deadline = Date.now() + timeoutMs;
+  while (Date.now() < deadline) {
+    const text = await readAnswer(bridge, tabId);
+    if (text !== "") {
+      return text;
+    }
+    // 按剩余时间睡：正好剩一个间隔时别睡满一秒把最后一次探测吞掉
+    const remaining = deadline - Date.now();
+    if (remaining <= 0) {
+      break;
+    }
+    await sleep(Math.min(POLL_INTERVAL_MS, remaining));
+  }
+  return "";
+}
+
+/** 探一次正文。失败当成空。 */
+async function readAnswer(bridge: ChromeBridge, tabId: number): Promise<string> {
+  try {
+    const value = await bridge.send(
+      "page.evaluate",
+      { expression: ANSWER_EXPRESSION, targetId: tabId },
+      10_000,
+    );
+    return typeof value === "string" ? value.trim() : "";
+  } catch {
+    return "";
+  }
+}
+
+function sleep(ms: number): Promise<void> {
+  return new Promise((resolve) => setTimeout(resolve, ms));
+}
