 /** 条目行：`- **标题**  — 摘要（热度）  |  链接` */
@@ -85,36 +89,41 @@ export function parseZhihu(md: string): ZhihuItem[] {
 /**
  * 从当天的抓取产物构建知乎章节。
  *
- * 读 `zhihu.md` → 解析问题与摘要片段 → 逐条直译。
+ * 读 `zhihu.md` → 解析问题与摘要片段 → 抓答案全文 → 逐条直译。
  * 不经模型：知乎正文不需要总结。
  */
 export async function buildZhihuSectionFromRuns(options: {
   runsDir: string;
   translator: Translator;
+  /** 抓答案全文的实现。默认走 `fetchZhihuAnswer`，测试可注入替身。 */
+  expand?: ExpandZhihuDeps;
 }): Promise<DigestSection> {
   const raw = await readFile(join(options.runsDir, SOURCE_FILES.zhihu), "utf8");
   const items = parseZhihu(raw);
   if (items.length === 0) {
     throw new Error("没有抓到条目");
   }
-  return buildZhihuSection({ items, translator: options.translator });
+  return buildZhihuSection({ items, translator: options.translator, expand: options.expand });
 }

 /**
  * 构建知乎章节。
  *
- * 每条都是「问题 + 答案摘要片段」的直译：左列英文、右列繁中。
- * 卡片标题保持中文原题（点进去是问题页），正文才是翻译。
+ * 先抓每条问题的第一个答案全文，每条都是「问题 + 正文」的直译：
+ * 左列英文、右列繁中。卡片标题保持中文原题（点进去是问题页），正文才是翻译。
  */
 export async function buildZhihuSection(options: {
   items: ZhihuItem[];
   translator: Translator;
+  /** 抓答案全文的实现。默认走 `fetchZhihuAnswer`，测试可注入替身。 */
+  expand?: ExpandZhihuDeps;
 }): Promise<DigestSection> {
   const { items, translator } = options;

-  const texts = await toBilingual(items.map((item) => sourceText(item)), translator);
+  const expanded = await expandZhihu(items, options.expand ?? {});
+  const texts = await toBilingual(expanded.map((item) => sourceText(item)), translator);

-  const digestItems: DigestItem[] = items.map((item, index) => {
+  const digestItems: DigestItem[] = expanded.map((item, index) => {
     const text = texts[index];
     const digest: DigestItem = {
       title: item.title,
@@ -135,15 +144,70 @@ export async function buildZhihuSection(options: {
   };
 }

+/** 抓答案全文的实现。默认走 `fetchZhihuAnswer`，测试可注入替身。 */
+export interface ExpandZhihuDeps {
+  fetchAnswer?: (url: string) => Promise<ZhihuAnswerOutcome>;
+}
+
+/**
+ * 把每条问题的第一个答案全文抓下来。
+ *
+ * - 串行抓：Chrome 里并发开多个标签页会互相抢焦点 / 抢渲染，收益是负的；
+ * - 采纳条件：够长（≥ `MIN_ANSWER_CHARS`）**且**比摘要片段长。第二个条件防的是
+ *   「登录提示 / 折叠占位 / 只有标题的壳」——它们可能过 200 字，却比摘要还短；
+ * - 抓不到或没有链接：原样返回，正文仍是摘要片段；每条一条 info 日志，整批不抛错。
+ */
+export async function expandZhihu(items: ZhihuItem[], deps: ExpandZhihuDeps = {}): Promise<ZhihuItem[]> {
+  const fetchAnswer = deps.fetchAnswer ?? ((url: string) => fetchZhihuAnswer(url));
+
+  const expanded: ZhihuItem[] = [];
+  for (const item of items) {
+    expanded.push(await expandZhihuOne(item, fetchAnswer));
+  }
+  return expanded;
+}
+
+/** 抓一条问题的答案全文。每条的结果打一条 info 日志。 */
+async function expandZhihuOne(
+  item: ZhihuItem,
+  fetchAnswer: (url: string) => Promise<ZhihuAnswerOutcome>,
+): Promise<ZhihuItem> {
+  const chars = item.excerpt.length;
+  if (item.url === "") {
+    logger.info("zhihu answer skipped", { title: item.title, reason: "没有链接", chars });
+    return item;
+  }
+
+  const outcome = await fetchAnswer(item.url);
+  if (!outcome.ok) {
+    logger.info("zhihu answer skipped", { title: item.title, reason: outcome.reason, chars });
+    return item;
+  }
+
+  if (outcome.text.length < MIN_ANSWER_CHARS || outcome.text.length <= item.excerpt.length) {
+    logger.info("zhihu answer skipped", {
+      title: item.title,
+      reason: `全文 ${outcome.text.length} 字，不够长或没比摘要长`,
+      chars,
+    });
+    return item;
+  }
+
+  logger.info("zhihu answer expanded", { title: item.title, chars: outcome.text.length });
+  return { ...item, fullText: outcome.text };
+}
+
 /**
- * 一条知乎内容的原文：问题 + 摘要片段。
+ * 一条知乎内容的原文：问题 + 正文。
  *
- * 问题和摘要是一段话的两截，分开翻会丢上下文（读者只看到摘要，
- * 不知道在问什么），所以拼成一段一起翻。
+ * 有全文就用全文（摘要片段只是导语，不是答案）；没有就退回摘要片段。
+ * 问题和正文是一段话的两截，分开翻会丢上下文（读者只看到正文，不知道在问什么），
+ * 所以拼成一段一起翻。
  */
 function sourceText(item: ZhihuItem): string {
-  if (item.excerpt === "") {
+  const body = item.fullText !== undefined && item.fullText !== "" ? item.fullText : item.excerpt;
+  if (body === "") {
     return item.title;
   }
-  return `${item.title}\n\n${item.excerpt}`;
+  return `${item.title}\n\n${body}`;
 }
diff --git a/test/chrome/zhihu.test.ts b/test/chrome/zhihu.test.ts
new file mode 100644
index 0000000..e327ed2
--- /dev/null
+++ b/test/chrome/zhihu.test.ts
@@ -0,0 +1,202 @@
+import { describe, expect, it, spyOn } from "bun:test";
+import { MIN_ANSWER_CHARS, fetchZhihuAnswer } from "../../src/chrome/zhihu.ts";
+import { ChromeBridge } from "../../src/chrome/bridge.ts";
+
+const URL = "https://www.zhihu.com/question/2101846693520085716";
+
+/** 一段够长的答案正文（超过 MIN_ANSWER_CHARS）。 */
+const ANSWER = "知乎答案第一段。".repeat(40);
+
+/** 假桥：按动作名返回预设结果，并记录调用顺序。 */
+function stubBridge(
+  handler: (action: string, params: Record<string, unknown>) => unknown,
+  options: { connected?: boolean } = {},
+): {
+  bridge: ChromeBridge;
+  calls: { action: string; params: Record<string, unknown> }[];
+} {
+  const calls: { action: string; params: Record<string, unknown> }[] = [];
+  const bridge = {
+    role: "server" as const,
+    status: async () => ({
+      url: "http://127.0.0.1:0",
+      mode: "server" as const,
+      connected: options.connected ?? true,
+      queuedCommands: 0,
+      pendingCommands: 0,
+    }),
+    stop: async () => undefined,
+    send: async (action: string, params: Record<string, unknown> = {}) => {
+      calls.push({ action, params });
+      return handler(action, params);
+    },
+  } as unknown as ChromeBridge;
+  return { bridge, calls };
+}
+
+/** 只处理 tab.new / page.evaluate / tab.close 的假桥。 */
+function answerBridge(text: string | (() => string)): ReturnType<typeof stubBridge> {
+  return stubBridge((action) => {
+    if (action === "tab.new") {
+      return { tab: { id: 42 } };
+    }
+    if (action === "page.evaluate") {
+      return typeof text === "function" ? text() : text;
+    }
+    return { ok: true };
+  });
+}
