export async function fetchTwitterRaw(options: {
  dataDir: string;
  date: string;
  bridge?: ChromeBridge;
  minTweets?: number;
}): Promise<TwitterRawResult> {
  const bridge = options.bridge ?? (await ChromeBridge.connect());
  const ownsBridge = options.bridge === undefined;
