    await mkdir(dir, { recursive: true });
    await writeFile(join(dir, "twitter_raw.txt"), raw, "utf8");

    return { ok: true, count: tweets.length, role: bridge.role };
  } catch (error) {
    return { ok: false, count: 0, error: (error as Error).message };
  } finally {
    if (ownsBridge) {
      await bridge.stop();
    }
  }
}

