/**
 * 知乎热榜的原始数据解析。
 *
 * `scripts/fetch.sh` 产出的 `zhihu.md` 每行一条：
 *
 * ```
 * - **问题标题**  — 答案摘要片段（359 万热度）  |  https://www.zhihu.com/question/<id>
 * ```
 *
 * 知乎不走大模型总结：正文直接翻译成英文与繁中，所以这里要把
 * 标题与摘要片段原样还原出来。
 */

import { readFile } from "node:fs/promises";
import { join } from "node:path";
import { MIN_ANSWER_CHARS, fetchZhihuAnswer, type ZhihuAnswerOutcome } from "./chrome/zhihu.ts";
import { logger } from "./logo.ts";
import { toBilingual, type Translator } from "./translate.ts";
import type { DigestItem, DigestSection } from "./types.ts";
import { SOURCE_FILES, SOURCE_TITLES } from "./types.ts";

/** 知乎热榜的一条。 */
export interface ZhihuItem {
  /** 问题标题（原文，中文）。 */
  title: string;
  /** 答案摘要片段（原文）。没有就是空串。 */
  excerpt: string;
  /** 问题链接。 */
  url: string;
  /** 热度，如 "359 万热度"。 */
  heat?: string;
  /** 答案全文（抓到时才有）。正文优先用它，没有就退回摘要片段。 */
  fullText?: string;
}

/** 条目行：`- **标题**  — 摘要（热度）  |  链接` */
const ITEM_PATTERN = /^-\s+\*\*(.+?)\*\*/;

/**
 * 解析 `zhihu.md`。
 *
 * 逐行匹配，认不出来就跳过——抓取失败时文件里是「⚠️ 抓取失敗：無數據」，
 * 那不是条目。
 */
export function parseZhihu(md: string): ZhihuItem[] {
  const items: ZhihuItem[] = [];

  for (const raw of md.split("\n")) {
    const line = raw.trim();
    const head = ITEM_PATTERN.exec(line);
    if (head === null) {
      continue;
    }

    const title = (head[1] ?? "").trim();
    if (title === "") {
      continue;
    }

    // 标题之后：`  — 摘要（热度）  |  链接`
    let rest = line.slice(head[0].length);

    let url = "";
    const pipe = rest.lastIndexOf("|");
    if (pipe !== -1) {
      url = rest.slice(pipe + 1).trim();
      rest = rest.slice(0, pipe);
    }

    let heat: string | undefined;
    const heatMatch = /（([^）]*)）\s*$/.exec(rest);
    if (heatMatch !== null) {
      heat = (heatMatch[1] ?? "").trim();
      rest = rest.slice(0, heatMatch.index);
    }

    const excerpt = rest.replace(/^\s*—\s*/, "").trim();

    const item: ZhihuItem = { title, excerpt, url };
    if (heat !== undefined && heat !== "") {
      item.heat = heat;
    }
    items.push(item);
  }

  return items;
}

/**
 * 从当天的抓取产物构建知乎章节。
 *
 * 读 `zhihu.md` → 解析问题与摘要片段 → 抓答案全文 → 逐条直译。
 * 不经模型：知乎正文不需要总结。
 */
export async function buildZhihuSectionFromRuns(options: {
  runsDir: string;
  translator: Translator;
  /** 抓答案全文的实现。默认走 `fetchZhihuAnswer`，测试可注入替身。 */
  expand?: ExpandZhihuDeps;
}): Promise<DigestSection> {
  const raw = await readFile(join(options.runsDir, SOURCE_FILES.zhihu), "utf8");
  const items = parseZhihu(raw);
  if (items.length === 0) {
    throw new Error("没有抓到条目");
  }
  return buildZhihuSection({ items, translator: options.translator, expand: options.expand });
}

/**
 * 构建知乎章节。
 *
 * 先抓每条问题的第一个答案全文，每条都是「问题 + 正文」的直译：
 * 左列英文、右列繁中。卡片标题保持中文原题（点进去是问题页），正文才是翻译。
 */
export async function buildZhihuSection(options: {
  items: ZhihuItem[];
  translator: Translator;
  /** 抓答案全文的实现。默认走 `fetchZhihuAnswer`，测试可注入替身。 */
  expand?: ExpandZhihuDeps;
}): Promise<DigestSection> {
  const { items, translator } = options;

  const expanded = await expandZhihu(items, options.expand ?? {});
  const texts = await toBilingual(expanded.map((item) => sourceText(item)), translator);

  const digestItems: DigestItem[] = expanded.map((item, index) => {
    const text = texts[index];
    const digest: DigestItem = {
      title: item.title,
      en: text?.en ?? item.title,
      zh: text?.zh ?? "",
    };
    if (item.url !== "") {
      digest.url = item.url;
    }
    return digest;
  });

  return {
    key: "zhihu",
    title: SOURCE_TITLES.zhihu,
    kind: "items",
    items: digestItems,
  };
}

/** 抓答案全文的实现。默认走 `fetchZhihuAnswer`，测试可注入替身。 */
export interface ExpandZhihuDeps {
  fetchAnswer?: (url: string) => Promise<ZhihuAnswerOutcome>;
}

/**
 * 把每条问题的第一个答案全文抓下来。
 *
 * - 串行抓：Chrome 里并发开多个标签页会互相抢焦点 / 抢渲染，收益是负的；
 * - 采纳条件：够长（≥ `MIN_ANSWER_CHARS`）**且**比摘要片段长。第二个条件防的是
 *   「登录提示 / 折叠占位 / 只有标题的壳」——它们可能过 200 字，却比摘要还短；
 * - 抓不到或没有链接：原样返回，正文仍是摘要片段；每条一条 info 日志，整批不抛错。
 */
export async function expandZhihu(items: ZhihuItem[], deps: ExpandZhihuDeps = {}): Promise<ZhihuItem[]> {
  const fetchAnswer = deps.fetchAnswer ?? ((url: string) => fetchZhihuAnswer(url));

  const expanded: ZhihuItem[] = [];
  for (const item of items) {
    expanded.push(await expandZhihuOne(item, fetchAnswer));
  }
  return expanded;
}

/** 抓一条问题的答案全文。每条的结果打一条 info 日志。 */
async function expandZhihuOne(
  item: ZhihuItem,
  fetchAnswer: (url: string) => Promise<ZhihuAnswerOutcome>,
): Promise<ZhihuItem> {
  const chars = item.excerpt.length;
  if (item.url === "") {
    logger.info("zhihu answer skipped", { title: item.title, reason: "没有链接", chars });
    return item;
  }

  const outcome = await fetchAnswer(item.url);
  if (!outcome.ok) {
    logger.info("zhihu answer skipped", { title: item.title, reason: outcome.reason, chars });
    return item;
  }

  if (outcome.text.length < MIN_ANSWER_CHARS || outcome.text.length <= item.excerpt.length) {
    logger.info("zhihu answer skipped", {
      title: item.title,
      reason: `全文 ${outcome.text.length} 字，不够长或没比摘要长`,
      chars,
    });
    return item;
  }

  logger.info("zhihu answer expanded", { title: item.title, chars: outcome.text.length });
  return { ...item, fullText: outcome.text };
}

/**
 * 一条知乎内容的原文：问题 + 正文。
 *
 * 有全文就用全文（摘要片段只是导语，不是答案）；没有就退回摘要片段。
 * 问题和正文是一段话的两截，分开翻会丢上下文（读者只看到正文，不知道在问什么），
 * 所以拼成一段一起翻。
 */
function sourceText(item: ZhihuItem): string {
  const body = item.fullText !== undefined && item.fullText !== "" ? item.fullText : item.excerpt;
  if (body === "") {
    return item.title;
  }
  return `${item.title}\n\n${body}`;
}

